// Create an event
event := &scheduling.Event{
    StartTime: time.Now(),
    EndTime:   time.Now().Add(1 * hour),
    Type:      scheduling.EventTypeTask,
    Task:      &scheduling.Task{
        Description: "my-task",
        Properties: map[string]string{
            "focus-mode": true,
        },
    },
}

// Set the event as focus mode
event.Properties["focus-mode"] = true

// Add the event to the schedule
provider.AddEvent(event)

// Start the scheduler
scheduler := scheduling.NewScheduler(provider)
go func() {
    if err := scheduler.Run(); err != nil {
        log.Fatal(err)
    }
}()

// Get the current events
currentEvents := provider.GetEvents(context.Background())

for _, event := range currentEvents.Events {
